// Concatenates every migration into supabase/setup_all.sql so the whole database can
// be created by pasting one file into the Supabase SQL editor.
//   node scripts/build-setup-sql.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dir = path.join(root, 'supabase', 'migrations');
const files = fs.readdirSync(dir).filter((f) => f.endsWith('.sql')).sort();
const out = [
  '-- Tosinfinity Academy: complete database setup.',
  '-- GENERATED by scripts/build-setup-sql.mjs from supabase/migrations. Do not edit by hand.',
  '-- Safe to run more than once. Paste into Supabase → SQL Editor → Run.',
  '',
  ...files.flatMap((f) => [`-- ===================== ${f} =====================`, fs.readFileSync(path.join(dir, f), 'utf8').trim(), '']),
].join('\n');
fs.writeFileSync(path.join(root, 'supabase', 'setup_all.sql'), out);
console.log(`Wrote supabase/setup_all.sql from ${files.length} migrations (${Math.round(out.length / 1024)} KB).`);
